/**
 * Tests for lib/session-once: the once-per-session flag store (#4652).
 */

import { existsSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, test } from 'vitest';
import { claimOncePerSession } from '../../lib/session-once.js';

describe('claimOncePerSession', () => {
  let projectDir: string;
  beforeEach(() => {
    projectDir = mkdtempSync(join(tmpdir(), 'session-once-'));
  });
  afterEach(() => {
    rmSync(projectDir, { recursive: true, force: true });
  });

  test('first claim is true, the second in the same session is false', () => {
    expect(claimOncePerSession(projectDir, 'hint', 'sess-1')).toBe(true);
    expect(claimOncePerSession(projectDir, 'hint', 'sess-1')).toBe(false);
  });

  test('a new session or a new name claims again', () => {
    expect(claimOncePerSession(projectDir, 'hint', 'sess-1')).toBe(true);
    expect(claimOncePerSession(projectDir, 'hint', 'sess-2')).toBe(true);
    expect(claimOncePerSession(projectDir, 'other', 'sess-1')).toBe(true);
  });

  test('writes the flag under .claude/state', () => {
    claimOncePerSession(projectDir, 'hint', 'sess-1');
    expect(existsSync(join(projectDir, '.claude', 'state', 'hint-sess-1.flag'))).toBe(true);
  });

  test('a hostile session id stays inside the state dir', () => {
    expect(claimOncePerSession(projectDir, 'hint', '../../escape')).toBe(true);
    expect(claimOncePerSession(projectDir, 'hint', '../../escape')).toBe(false);
    expect(existsSync(join(projectDir, '.claude', 'escape.flag'))).toBe(false);
    expect(existsSync(join(projectDir, '.claude', 'state', 'hint-______escape.flag'))).toBe(true);
  });

  test('an unwritable state dir still returns true (the hint fires)', () => {
    // A FILE where the .claude dir should be makes mkdir fail.
    writeFileSync(join(projectDir, '.claude'), 'not a dir');
    expect(claimOncePerSession(projectDir, 'hint', 'sess-1')).toBe(true);
    expect(claimOncePerSession(projectDir, 'hint', 'sess-1')).toBe(true);
  });
});
